const CLAVE = 'preferencias';

const porDefecto = {
  tema: 'claro',
  idioma: 'es',
  notificaciones: true,
};

export function leerPreferencias() {
  const guardado = localStorage.getItem(CLAVE);
  if (!guardado) return porDefecto;
  return JSON.parse(guardado);
}

export function guardarPreferencia(clave, valor) {
  const prefs = leerPreferencias();
  prefs[clave] = valor;
  localStorage.setItem(CLAVE, prefs);
}

export function usarModoOscuro() {
  const prefs = leerPreferencias();
  return prefs.tema === 'oscuro' || window.matchMedia('(prefers-color-scheme: dark)').matches;
}

export function guardarToken(token) {
  localStorage.setItem('token', token);
}
